package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.widget.*;import android.text.InputType;import org.json.*;import java.util.*;
public final class TuningEditor{
 private static String manage(Activity a,String action,JSONObject req)throws Exception{return(String)Class.forName("org.efootballrevival.runtimeprobe.EmbeddedGateway").getMethod("manage",Context.class,String.class,String.class).invoke(null,a,action,req.toString());}
 private static void error(Activity a,Exception e){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("Player Editor").setMessage(String.valueOf(e.getCause()==null?e.getMessage():e.getCause().getMessage())).setPositiveButton("Close",null).show();}
 public static void attachSkills(Activity a,LinearLayout panel,JSONObject player){Button b=new Button(a);b.setText("Edit Innate Skills");b.setAllCaps(false);b.setOnClickListener(v->{b.setEnabled(false);new Thread(()->{try{JSONObject data=new JSONObject(manage(a,"ui77_skills_get",player));a.runOnUiThread(()->{b.setEnabled(true);if(!a.isFinishing())skills(a,player,data);});}catch(Exception e){a.runOnUiThread(()->{b.setEnabled(true);error(a,e);});}},"InnateSkillsLoad").start();});panel.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 private static void save(Activity a,AlertDialog d,String action,JSONObject req){d.getButton(-1).setEnabled(false);new Thread(()->{try{JSONObject reply=new JSONObject(manage(a,action,req));if(!reply.optBoolean("saved",false))throw new Exception("Save was not confirmed");a.runOnUiThread(()->{d.dismiss();Toast.makeText(a,"Saved. Reopen player details to refresh.",Toast.LENGTH_LONG).show();});}catch(Exception e){a.runOnUiThread(()->{d.getButton(-1).setEnabled(true);error(a,e);});}},"PlayerTuningSave").start();}
 private static void skills(Activity a,JSONObject player,JSONObject data){JSONArray choices=data.optJSONArray("choices"),selected=data.optJSONArray("selected");if(choices==null)return;int n=choices.length();String[] names=new String[n];int[] ids=new int[n];boolean[] checked=new boolean[n];HashSet<Integer> before=new HashSet<>();if(selected!=null)for(int i=0;i<selected.length();i++)before.add(selected.optInt(i));for(int i=0;i<n;i++){JSONObject row=choices.optJSONObject(i);ids[i]=row.optInt("id");checked[i]=before.contains(ids[i]);names[i]=row.optString("label")+(checked[i]?" · Current":"");}AlertDialog d=new AlertDialog.Builder(a).setTitle("Innate Skills · "+before.size()+" current").setMultiChoiceItems(names,checked,(dialog,i,on)->checked[i]=on).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.show();ResponsiveUi.fit(a,d);d.getButton(-1).setOnClickListener(v->{try{JSONArray out=new JSONArray();for(int i=0;i<n;i++)if(checked[i])out.put(ids[i]);JSONObject req=new JSONObject(player.toString()).put("selected",out);save(a,d,"ui77_skills_apply",req);}catch(Exception e){error(a,e);}});}
}
